<?php use Aibid\Http\View as V; ?>
<div class="page-heading"><div><span class="eyebrow">ACCESO AL PANEL</span><h1>Administradores</h1><p>Permisos definidos y segundo factor obligatorio para cada cuenta.</p></div></div>
<div class="row g-4"><div class="col-xl-8"><section class="panel"><div class="panel-heading"><h2>Cuentas registradas</h2></div><?php foreach ($users as $user): ?><article class="user-record"><div class="d-flex justify-content-between gap-3"><div><strong><?= V::escape($user['display_name']) ?></strong><small class="cell-sub"><?= V::escape($user['login']) ?></small></div><span class="tag <?= $user['state']==='active'?'tag-green':'' ?>"><?= $user['state']==='active'?'Activa':'Deshabilitada' ?></span></div><div class="user-role-line"><?= V::escape(V::role($user['role'])) ?> <span>·</span> <?= $user['has_mfa']?'MFA configurado':'MFA pendiente de configurar' ?></div><details><summary>Modificar permisos o acceso</summary><form class="stack-form mt-3" method="post" action="/admin/users/<?= V::escape($user['id_text']) ?>"><?php V::fields($csrf); ?><label>Rol<select class="form-select mt-2" name="role"><?php foreach(['superadmin','operator','viewer'] as $role): ?><option value="<?= $role ?>" <?= $user['role']===$role?'selected':'' ?>><?= V::escape(V::role($role)) ?></option><?php endforeach; ?></select></label><label>Estado<select class="form-select mt-2" name="state"><option value="active">Activa</option><option value="disabled" <?= $user['state']==='disabled'?'selected':'' ?>>Deshabilitada</option></select></label><label>Motivo<input class="form-control mt-2" name="reason" maxlength="500" required></label><label>Tu contraseña<input class="form-control mt-2" name="password" type="password" autocomplete="current-password" required></label><label>Código de autenticación nuevo<input class="form-control mt-2" name="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" required></label><p class="small text-secondary">Guardar cerrará las sesiones existentes de esta cuenta.</p><button class="btn btn-outline-primary">Guardar cambios</button></form></details></article><?php endforeach; ?></section></div>
<div class="col-xl-4"><form class="panel form-panel" method="post" action="/admin/users/create"><?php V::fields($csrf); ?><h2>Nueva cuenta</h2><div class="stack-form mt-3"><label>Nombre<input class="form-control mt-2" name="name" maxlength="190" required></label><label>Correo de acceso<input class="form-control mt-2" type="email" name="login" maxlength="190" autocomplete="off" required></label><label>Rol<select class="form-select mt-2" name="role"><option value="operator">Operador de licencias</option><option value="viewer">Consulta</option><option value="superadmin">Superadministrador</option></select></label><label>Contraseña inicial<input class="form-control mt-2" type="password" name="new_password" minlength="12" maxlength="1024" autocomplete="new-password" required></label><div class="note-box">Comparte las credenciales por un canal seguro. La persona configurará MFA al ingresar.</div><label>Tu contraseña<input class="form-control mt-2" name="password" type="password" autocomplete="current-password" required></label><label>Tu código de autenticación nuevo<input class="form-control mt-2" name="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" required></label><button class="btn btn-primary">Crear administrador</button></div></form></div></div>
